function valuesSeenTwice(nums: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    const v = Math.abs(nums[i]);
    if (nums[v - 1] < 0) out.push(v);
    else nums[v - 1] = -nums[v - 1];
  }
  return out;
}

